import{_ as t,o as n,c as r,ag as s}from"./chunks/framework.BtBS1okS.js";const g=JSON.parse(`{"title":"Les activités","description":"","frontmatter":{},"headers":[],"relativePath":"handout-08-activites.md","filePath":"handout-08-activites.md","handout":{"fichier":"handout-08-activites.md","markdown":"# Handout — Les activités\\n\\n**Le nouveau PDLC IA — ce qui change pour votre équipe · Zenika · support d'activité**\\n\\nLes activités de la formation, pour les refaire avec votre équipe : la consigne, le matériel et ce qu'on en retient.\\n\\n## Ranger dans le Nexus (4 min, optionnelle)\\n\\n_Module 3 · slide « Activité — Ranger dans le Nexus »_\\n\\n**Objectif** : placer six informations familières dans le Context Nexus, avec deux coordonnées chacune : un registre (Knowledge, Purpose, Contracts, Process) et un niveau (organisation, programme, équipe).\\n\\n**Déroulé**\\n\\n1. Par deux, recopiez la grille vide ci-dessous, ou notez simplement « n° → registre, niveau » (à distance, dans le chat : « 1 → Contracts, organisation »).\\n2. Placez les six cartes en 2 minutes. Une carte peut aller dans plusieurs cases, ou dans aucune.\\n3. Correction carte par carte, puis débrief.\\n\\n**Les cartes** (chez Vélora, groupe hôtelier fictif)\\n\\n1. « Toutes nos interfaces respectent le niveau WCAG AA. »\\n2. Le glossaire partagé par les équipes du programme.\\n3. « Rappel de départ : −x % de départs non annoncés à la réception. »\\n4. Le runbook « VelNotif ne répond plus ».\\n5. L'ADR « on passe par VelNotif, pas par un prestataire d'envoi externe ».\\n6. « Sur un écran de suivi, l'équipe accepte 400 ms de temps de réponse au lieu des 200 ms fixés par le groupe. »\\n\\n**La grille**\\n\\n|                  | Knowledge | Purpose | Contracts | Process |\\n| ---------------- | --------- | ------- | --------- | ------- |\\n| **Organisation** |           |         |           |         |\\n| **Programme**    |           |         |           |         |\\n| **Équipe**       |           |         |           |         |\\n\\n**Pour vous aider** : le handout « Le Context Nexus », sections « Les quatre registres », « Découper une ADR », « La grille registres × niveaux » et « Étendre, déroger, contredire ».\\n\\n**À retenir**\\n\\n- Un registre dit ce qu'est une information ; un niveau dit jusqu'où elle s'applique.\\n- Une ADR ne se range pas d'un bloc.\\n- Une équipe ne contredit pas une règle du groupe : elle déroge en le déclarant, avec l'approbation du niveau au-dessus.\\n\\n**Avec votre équipe** : lesquelles de ces six informations existent déjà par écrit chez vous, à quel niveau, et où ?\\n\\n## Distribuer les casquettes (8 min)\\n\\n_Module 4 · slide « Activité — Distribuer les casquettes »_\\n\\n**Objectif** : nommer un porteur pour chaque casquette de votre équipe, voir qui porte trop, et choisir un levier.\\n\\n**Déroulé**\\n\\n1. Notez les membres de votre équipe, avec leurs initiales seulement : on regarde l'équipe, on ne juge personne.\\n2. Placez un porteur sur chaque casquette (4 minutes, seul).\\n   - Une personne peut porter plusieurs casquettes.\\n   - L'Orchestrator peut tourner entre 2 ou 3 personnes : partagez sa charge.\\n   - Le Decision Guarantor est une seule personne, nommée.\\n3. Additionnez la charge indicative par personne.\\n4. Entourez la personne la plus chargée et choisissez un levier : répartir, faire tourner, ou signaler un écart (un profil qui manque).\\n5. Comparez à deux (2 minutes), puis débrief.\\n\\n**La grille**\\n\\n| Casquette                                | Qui ? | Charge indicative |\\n| ---------------------------------------- | ----- | ----------------- |\\n| Context Engineer                         |       | ~0,25 ETP         |\\n| Specification Engineer                   |       | ~0,35 ETP         |\\n| Agentic Workflow Orchestrator            |       | ~0,3 ETP          |\\n| Decision Guarantor                       |       | ~0,15 ETP         |\\n| Notre contact Evaluation Engineer (pool) |       | —                 |\\n\\n**Pour vous aider** : le handout « Équipe et nouveaux rôles », sections « Les quatre casquettes de l'équipe » et « Le premier goulot à repérer ».\\n\\n**À retenir**\\n\\n- Nommer les casquettes avant que l'outillage n'arrive : sinon, ce sont les outils qui décident qui fait quoi.\\n- La première surcharge est souvent la personne la plus sollicitée aujourd'hui.\\n- Une casquette que personne ne peut porter est un écart à remonter, pas une faute.\\n\\n**Avec votre équipe** : refaites la grille ensemble, et demandez à chaque personne si sa charge lui paraît réaliste.\\n\\n## Gain ou pas ? (3 min)\\n\\n_Module 6 · slide « Exercice éclair — Gain ou pas ? »_\\n\\n**Objectif** : lire des indicateurs comme un manager, la vitesse avec la qualité, le coût et l'expérience, sans conclure trop vite.\\n\\n**Déroulé**\\n\\n1. Lisez les trois équipes, comparées à leur mesure de référence.\\n2. Pour chacune, tranchez : « oui », « pas encore » ou « attendre » (à distance, dans le chat : « A … , B … , C … »).\\n3. Correction, puis débrief.\\n\\n**Les trois équipes**\\n\\n| Équipe | Ce qu'on observe, par rapport à la référence                                     |\\n| ------ | -------------------------------------------------------------------------------- |\\n| **A**  | Lead time −25 % ; taux de reprise +40 %                                          |\\n| **B**  | Lead time +10 % au deuxième mois ; bugs stables ; enquête d'expérience en hausse |\\n| **C**  | Complexité livrée +15 % ; bugs stables ; coût IA par point en baisse             |\\n\\n**Pour vous aider** : le handout « Déploiement et mesure », sections « Mesurer la valeur, pas l'adoption », « Les sept indicateurs » et « La courbe en J ».\\n\\n**À retenir**\\n\\n- Une vitesse ne se lit jamais seule : la qualité et le coût vont avec.\\n- Une baisse au début est attendue ; une baisse qui dure est un signal.\\n- Sans mesure de référence prise avant l'outillage, aucun gain ne se démontre.\\n\\n**Avec votre équipe** : quelle donnée vous manquerait aujourd'hui pour trancher ?\\n"}}`),i={name:"handout-08-activites.md"};function a(o,e,u,l,d,p){return n(),r("div",null,[...e[0]||(e[0]=[s("",38)])])}const m=t(i,[["render",a]]);export{g as __pageData,m as default};
